#ifndef MATERIAL_SHARED_ATLAS_H
#define MATERIAL_SHARED_ATLAS_H
#include "material_shared_pullback.h"
namespace shared_target {
static S holomorphic_power(S z,Q exponent){need(exponent<0&&sf::lower(z)>0,"negative-power analytic disk stays in positive half-plane");S center=mf::power(S(z.n),exponent);Q slope=sf::mag(S(-exponent)*mf::power(S(sf::lower(z)),exponent-Q(1)));center.e=sf::add(center.e,sf::mul(slope,z.e));return center;}
static S holomorphic_exp(S z){Q n=expq(z.n),tail=expm1q(z.e);S center(n,mf::libm_error(n));Q variation=sf::mul(sf::mag(center),sf::add(tail,mf::libm_error(tail)));center.e=sf::add(center.e,variation);return center;}
static std::array<S,12> reference_moments(const curved::Packet&p,const sd::Point&q,S radius,const Thermal&context){same_control(context);const auto&f=q.field;S inner=holomorphic_exp(S(2)*(radius-sf::exact(p.parameters[4]))/sf::exact(p.parameters[8])),outer=holomorphic_exp(S(2)*(radius-sf::exact(p.parameters[5]))/sf::exact(p.parameters[8])),rho=sf::exact(p.parameters[6])+sf::exact(p.parameters[9])/(radius+sf::exact(p.parameters[7]))*inner/(S(1)+inner)/(S(1)+outer),U=sf::exact(p.parameters[2])/(sf::exact(p.parameters[1])-S(1))*holomorphic_power(f.J,Q(1)-Q(p.parameters[1])),P=(sf::exact(p.parameters[1])-S(1))*U/(f.J+sf::exact(context.delta)),x=f.position[0],y=f.position[1],vx=f.velocity[0],vy=f.velocity[1],potential=x*x+y*y+sf::exact(p.parameters[3])*sf::exact(p.parameters[3]);std::array<S,12>z;z[MASS]=rho;z[PX]=rho*vx;z[PY]=rho*vy;z[ANGULAR]=rho*(x*vy-y*vx);z[KINETIC]=S(Q(.5L))*rho*(vx*vx+vy*vy);z[THERMAL]=U;z[VOLUME]=f.J;z[QX]=rho*x;z[QY]=rho*y;z[POLAR]=rho*(x*x+y*y);z[THERMAL_RATE]=-P*(f.J*(f.grad_v[0]+f.grad_v[3])+sf::exact(context.delta_dot));z[POTENTIAL]=-rho*holomorphic_power(potential,Q(-.5L));return z;}
struct Panel {int chart=0,ir=0,it=0,nr=0,nt=0;S slo,shi,tlo,thi;};
struct Atlas {std::vector<Panel>panel;Q reference_radius_lower=0,physical_scale=0;uint64_t predicted_positive_queries=0;bool cost_pass=false;char reason[192]={};};
static Atlas whole_atlas(const curved::Packet&p,const sd::Compiled&m,uint64_t query_budget){Atlas out;try{Q r2=0;for(int k=0;k<2;k++){Q lo=sf::lower(m.base.vertex[0][k]),hi=sf::upper(m.base.vertex[0][k]);for(int a=1;a<3;a++){lo=std::min(lo,sf::lower(m.base.vertex[a][k]));hi=std::max(hi,sf::upper(m.base.vertex[a][k]));}Q d=lo>0?lo:hi<0?-hi:Q(0);r2=mf::FP<Q>::down(r2+mf::FP<Q>::down(d*d));}need(r2>0,"origin-containing whole source needs the density-scale graded atlas");out.reference_radius_lower=sf::lower(mf::root(S(r2)));out.physical_scale=std::min(out.reference_radius_lower,Q(p.parameters[3]))/Q(8);need(out.physical_scale>0,"positive input-singularity distance for atlas");auto charts=sd::charts(m);for(int ci=0;ci<6;ci++){auto r=frame(m,charts[ci],sf::range(0,1));Q D=std::max(sf::mag(r.D[0]),sf::mag(r.D[1])),E=std::max(sf::mag(r.E[0]),sf::mag(r.E[1]));int nr=std::max(1,int(ceilq(D/out.physical_scale))),nt=std::max(4,int(ceilq(E/out.physical_scale)));need(nr>0&&nt>0&&uint64_t(nr)*uint64_t(nt)<=query_budget/256,"deterministic atlas exceeds declared positive-query cost budget");for(int i=0;i<nr;i++)for(int j=0;j<nt;j++)out.panel.push_back({ci,i,j,nr,nt,S(i)/S(nr),S(i+1)/S(nr),S(j)/S(nt),S(j+1)/S(nt)});}out.predicted_positive_queries=out.panel.size()*256;need(out.predicted_positive_queries<=query_budget,"deterministic total atlas exceeds declared cost budget");out.cost_pass=true;snprintf(out.reason,sizeof(out.reason),"finite_atlas_from_reference_density_and_softening_distances");}catch(const std::exception&e){snprintf(out.reason,sizeof(out.reason),"%s",e.what());}return out;}
// Gauss16 integrates constant*reference-Jacobian exactly (a degree-one
// polynomial). Bound the SAME integral after removing that exact part.
// This prevents a constant physical field from imposing an artificial
// remainder floor. No quadrature degree or physical tolerance is changed.
static Certificate panel_certificate_on_chart(const curved::Packet&p,const sd::Compiled&m,const sd::Chart&chart,const Panel&panel,const Thermal&context){Certificate out;try{S ds=panel.shi-panel.slo,dt=panel.thi-panel.tlo,sm=(panel.slo+panel.shi)/S(2),tm=(panel.tlo+panel.thi)/S(2);auto center=sd::evaluate(m,chart,sm,tm);auto center_z=reference_moments(p,center,reference_radius(m,chart,sm,tm,center),context);Q majorant[12]={};for(int axis=0;axis<2;axis++){S u=axis?sf::range(0,1):S(Q(.5L),Q(1.25L)),v=axis?S(Q(.5L),Q(1.25L)):sf::range(0,1),s=panel.slo+ds*u,t=panel.tlo+dt*v;auto q=sd::evaluate(m,chart,s,t);auto z=reference_moments(p,q,reference_radius(m,chart,s,t,q),context);S jac=q.reference_jacobian*ds*dt;for(int k=0;k<12;k++){Q variation=sf::add(fabsq(z[k].n-center_z[k].n),z[k].e);majorant[k]=std::max(majorant[k],sf::mul(sf::mag(jac),variation));}}Q C=sf::mag(cauchy_coefficient());for(int k=0;k<12;k++)out.remainder[k]=sf::mul(C,majorant[k]);out.pass=true;snprintf(out.reason,sizeof(out.reason),"actual_reference_panel_all12_analytic_remainder_with_exact_constant_removal");}catch(const std::exception&e){snprintf(out.reason,sizeof(out.reason),"%s",e.what());}return out;}
static Certificate panel_certificate(const curved::Packet&p,const sd::Compiled&m,const Panel&panel,const Thermal&context){return panel_certificate_on_chart(p,m,sd::charts(m)[panel.chart],panel,context);}
}
#endif
